id: string; kind: RecordKind; title: string; cwd: string; 
/**
 * Branch it ran on, to offer "Recreate worktree" once the folder is gone
 */
branch: string | null; repoRoot: string | null; 
/**
 * Claude / Codex session id that `--resume` takes
 */
